mapper.select:
SELECT a.*, c.category_name FROM activity a LEFT JOIN activity_category c ON a.category_id = c.id
AND a.title LIKE CONCAT('%', #{title}, '%')
AND a.category_id = #{categoryId}
AND a.status = #{status}
ORDER BY a.created_at DESC

mapper.update:
UPDATE activity
title = #{title}, cover_image = #{coverImage}, category_id = #{categoryId}, location = #{location}, start_time = #{startTime}, end_time = #{endTime}, status = #{status}, max_participants = #{maxParticipants}, awards = #{awards}, rules = #{rules}, description = #{description}, contact = #{contact}, fee_type = #{feeType}, fee_amount = #{feeAmount},
WHERE id = #{id}
